                fx {
                    println(name, ": ", startT, "-", endT, " Room ", room, " (", dur, " min)");
                }
            }
        }
    }
    ret;
}

fn stripDots(s: Text) -> Text {
    let i: Int = 0;
    loop i < string_len(s) {
        if s[i] != "." {
            break;
        }
        i = i + 1;
    }
    ret s[i..];
}

