type Arrival {
    runner: Int = 0;
    station: Int = 0;
    minute: Int = 0;
}

fn main() -> Void {
    let arrivals: Arrival[] = [
        new Arrival { runner: 3, station: 1, minute: 10 },
        new Arrival { runner: 7, station: 1, minute: 10 },
        new Arrival { runner: 1, station: 1, minute: 20 },
        new Arrival { runner: 5, station: 2, minute: 21 },
        new Arrival { runner: 4, station: 3, minute: 30 },
        new Arrival { runner: 2, station: 4, minute: 40 },
        new Arrival { runner: 6, station: 4, minute: 42 },
        new Arrival { runner: 8, station: 4, minute: 42 }
    ];

    // station free time
    let free: Int[] = [0, 0, 0, 0, 0]; // index 1..4

    // results per runner
    let finishStation: Int[] = [0; 9];
    let finishMinute: Int[] = [0; 9];

    // sort arrivals by station, then minute, then runner number
    // simple approach: process each station independently

    loop station in 1..5 {
        // collect arrivals for this station
        let stArrivals: Arrival[] = [];
        loop a in arrivals {
            if a.station == station {
                stArrivals = stArrivals + [a];
            }
        }
        // sort by minute, then runner
        // simple bubble sort
        loop i in 0..length(stArrivals) {
            loop j in 0..(length(stArrivals) - 1 - i) {
                if stArrivals[j].minute > stArrivals[j+1].minute || 
                   (stArrivals[j].minute == stArrivals[j+1].minute && stArrivals[j].runner > stArrivals[j+1].runner) {
                    let tmp: Arrival = stArrivals[j];
                    stArrivals[j] = stArrivals[j+1];
                    stArrivals[j+1] = tmp;
                }
            }
        }
        let freeTime: Int = 0;
        loop a in stArrivals {
            let start: Int = a.minute;
            if start < freeTime {
                start = freeTime;
            }
            let fin: Int = start + 2;
            freeTime = fin;
            finishStation[a.runner] = station;
            finishMinute[a.runner] = fin;
        }
    }

    fx {
        loop r in 1..9 {
            println("Runner ", r, ": station ", finishStation[r], " finishes at minute ", finishMinute[r]);
        }
    }
    ret;
}

fn main() -> Void {
    let total: Int = 0;
    let first1: Int = 0;
    let twoBeforeThree: Int = 0;
    let fiveMiddle: Int = 0;
    let diffOk: Int = 0;
    let smallest: Int[] = [];

    loop a in 1..6 {
        loop b in 1..6 {
            if b == a { continue; }
            loop c in 1..6 {
                if c == a || c == b { continue; }
                loop d in 1..6 {
                    if d == a || d == b || d == c { continue; }
                    loop e in 1..6 {
                        if e == a || e == b || e == c || e == d { continue; }
                        total = total + 1;
                        if a == 1 { first1 = first1 + 1; }
                        if b < c { twoBeforeThree = twoBeforeThree + 1; }
                        if c == 5 { fiveMiddle = fiveMiddle + 1; }
                        if abs(a - b) >= 2 && abs(b - c) >= 2 && abs(c - d) >= 2 && abs(d - e) >= 2 {
                            diffOk = diffOk + 1;
                            if length(smallest) == 0 {
                                smallest = [a, b, c, d, e];
                            }
                        }
                    }
                }
            }
        }
    }

    fx {
        println("Total orderings: ", total);
        println("Orderings with frame 1 first: ", first1);
        println("Orderings where frame 2 comes before frame 3: ", twoBeforeThree);
        println("Orderings where frame 5 is in the middle position: ", fiveMiddle);
        println("Number of orderings where consecutive frames differ by at least 2: ", diffOk);
        if length(smallest) == 0 {
            println("Smallest such ordering: None");
        } else {
            println("Smallest such ordering: ", smallest[0], " ", smallest[1], " ", smallest[2], " ", smallest[3], " ", smallest[4]);
        }
    }
    ret;
}

fn lexLess(a: Text, b: Text) -> Bool {
    let la: Int = string_len(a);
    let lb: Int = string_len(b);
    let n: Int = min(la, lb);
    loop i in 0..n {
        if a[i] != b[i] {
            ret ord(a[i]) < ord(b[i]);
        }
    }
    ret la < lb;
}

fn main() -> Void {
    let total: Int = 0;
    let visit22: Int = 0;
    let noVisit22: Int = 0;
    let visitBoth: Int = 0;
    let twoRFirst3: Int = 0;
    let best: Text = "";
    let bestFound: Bool = false;

    loop mask in 0..64 {
        let moves: Text[] = [];
        let row: Int = 1;
        let col: Int = 1;
        let seen22: Bool = false;
        let seen13: Bool = false;
        let seen31: Bool = false;
        let rFirst3: Int = 0;

        loop step in 0..6 {
            let bit: Int = (mask >> step) & 1;
            let mv: Text = if bit == 1 { "D" } else { "R" };
            moves = moves + [mv];
            if bit == 1 {
                row = row + 1;
            } else {
                col = col + 1;
                if step < 3 {
                    rFirst3 = rFirst3 + 1;
                }
            }
            if row == 2 && col == 2 { seen22 = true; }
            if row == 1 && col == 3 { seen13 = true; }
            if row == 3 && col == 1 { seen31 = true; }
        }

        total = total + 1;
        if seen22 {
            visit22 = visit22 + 1;
        } else {
            noVisit22 = noVisit22 + 1;
        }
        if seen13 && seen31 {
            visitBoth = visitBoth + 1;
        }
        if rFirst3 == 2 {
            twoRFirst3 = twoRFirst3 + 1;
        }
        if seen22 {
            let routeText: Text = join(moves, " ");
            if !bestFound {
                best = routeText;
                bestFound = true;
            } else {
                if lexLess(routeText, best) {
                    best = routeText;
                }
            }
        }
    }

    fx {
        println("Total routes: ", total);
        println("Routes that visit cell (2,2): ", visit22);
        println("Routes that do not visit cell (2,2): ", noVisit22);
        println("Routes that visit both (1,3) and (3,1): ", visitBoth);
        println("Shortest route visiting cell (2,2): ", best);
        println("Number of routes with exactly 2 right moves in the first 3 steps: ", twoRFirst3);
    }
    ret;
}

type Song {
    letter: Text = "";
    count: Int = 0;
    order: Int = 0;
}

fn main() -> Void {
    let songs: Song[] = [
        new Song { letter: "A", count: 42, order: 0 },
        new Song { letter: "B", count: 17, order: 1 },
        new Song { letter: "C", count: 42, order: 2 },
        new Song { letter: "D", count: 8, order: 3 },
        new Song { letter: "E", count: 25, order: 4 },
        new Song { letter: "F", count: 17, order: 5 },
        new Song { letter: "G", count: 60, order: 6 },
        new Song { letter: "H", count: 30, order: 7 }
    ];

    // Sort by count desc, then order asc (insertion sort for stability)
    let n: Int = length(songs);
    loop i in 1..n {
        let key: Song = songs[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if songs[j].count < key.count || (songs[j].count == key.count && songs[j].order > key.order) {
                songs[j + 1] = songs[j];
                j = j - 1;
            } else {
                break;
            }
        }
        songs[j + 1] = key;
    }

    fx {
        println("Section 1 — Top plays:");
        loop i in 0..n {
            println("Rank ", i + 1, ": Song ", songs[i].letter, " (", songs[i].count, " plays)");
        }
    }

    // Distinct counts ascending with frequencies
    let counts: Int[] = [];
    let freqs: Int[] = [];
    loop i in 0..n {
        let c: Int = songs[i].count;
        let found: Bool = false;
        loop k in 0..length(counts) {
            if counts[k] == c {
                freqs[k] = freqs[k] + 1;
                found = true;
                break;
            }
        }
        if !found {
            counts = counts + [c];
            freqs = freqs + [1];
        }
    }

    // Sort counts ascending (insertion sort, carrying freqs)
    let m: Int = length(counts);
    loop i in 1..m {
        let kc: Int = counts[i];
        let kf: Int = freqs[i];
        let j: Int = i - 1;
        loop j >= 0 {
            if counts[j] > kc {
                counts[j + 1] = counts[j];
                freqs[j + 1] = freqs[j];
                j = j - 1;
            } else {
                break;
            }
        }
        counts[j + 1] = kc;
        freqs[j + 1] = kf;
    }

    fx {
        println("");
        loop i in 0..m {
            println(counts[i], " plays: used by ", freqs[i], " songs");
        }
    }
    ret;
}

