fn main() -> Void {
    let lines: Text[] = [
        "START:station=AA,minutes=15,km=3.2",
        "START:station=BB,minutes=8,km=1.5",
        "START:station=CC,minutes=22,km=5.7",
        "START:station=AA,minutes=12,km=2.8",
        "START:station=DD,minutes=30,km=7.1",
        "START:station=BB,minutes=18,km=4.3",
        "START:station=EE,minutes=6,km=1.1",
        "START:station=CC,minutes=25,km=6.4"
    ];

    let totalTrips: Int = 0;
    let totalKm: Real = 0.0;
    let fastTrips: Int = 0;

    let codes: Text[] = [];
    let counts: Int[] = [];
    let topStation: Text = "";
    let topCount: Int = 0;

    loop line in lines {
        let parts: Text[] = split(line, ",");
        let stationPart: Text = parts[0];
        let station: Text = stationPart[14..16];

        let minutesPart: Text = parts[1];
        let minutes: Int = parse_int(minutesPart[8..]);

        let kmPart: Text = parts[2];
        let km: Real = parse_float(kmPart[3..]);

        totalTrips = totalTrips + 1;
        totalKm = totalKm + km;

        let speed: Real = km * 60.0 / minutes;
        if speed > 18.0 {
            fastTrips = fastTrips + 1;
        }

        let idx: Int = index_of(codes, station);
        if idx == -1 {
            codes = codes + [station];
            counts = counts + [1];
            if 1 > topCount {
                topCount = 1;
                topStation = station;
            }
        } else {
            counts[idx] = counts[idx] + 1;
            if counts[idx] > topCount {
                topCount = counts[idx];
                topStation = station;
            }
        }
    }

    fx {
        println("TotalTrips=", totalTrips);
        println("TotalKm=", formatfloat(totalKm, 2));
        println("TopStation=", topStation);
        println("FastTrips=", fastTrips);
    }
    ret;
}

fn main() -> Void {
    let students: Text[] = ["A", "B", "C", "D"];
    let count: Int = 0;
    let results: Text[] = [];

    loop i1 in 0..4 {
        loop i2 in 0..4 {
            if i2 == i1 { continue; }
            loop i3 in 0..4 {
                if i3 == i1 || i3 == i2 { continue; }
                let i4: Int = 6 - i1 - i2 - i3;
                if i4 < 0 || i4 > 3 { continue; }
                if i4 == i1 || i4 == i2 || i4 == i3 { continue; }

                // assignment: desk1..desk4 = students[i1..i4]
                let s1: Text = students[i1];
                let s2: Text = students[i2];
                let s3: Text = students[i3];
                let s4: Text = students[i4];

                // Rule: A must sit at desk 2 or 3
                if !(s2 == "A" || s3 == "A") { continue; }
                // Rule: D must not sit at desk 1
                if s1 == "D" { continue; }
                // Rule: B and C not adjacent
                let bPos: Int = -1;
                let cPos: Int = -1;
                if s1 == "B" { bPos = 0; }
                if s2 == "B" { bPos = 1; }
                if s3 == "B" { bPos = 2; }
                if s4 == "B" { bPos = 3; }
                if s1 == "C" { cPos = 0; }
                if s2 == "C" { cPos = 1; }
                if s3 == "C" { cPos = 2; }
                if s4 == "C" { cPos = 3; }
                if abs(bPos - cPos) == 1 { continue; }

                let assignment: Text = s1 + s2 + s3 + s4;
                results = results + [assignment];
                count = count + 1;
            }
        }
    }

    results = sorted(results);
    fx {
        loop r in results {
            println(r);
        }
        println("Count: ", count);
    }
    ret;
}

fn main() -> Void {
    let selected: Bool = false;
    let paid: Bool = false;
    let dispenses: Int = 0;
    let ignored: Int = 0;
    let cmds: Text[] = ["1", "P", "V", "2", "3", "P", "1", "V", "4", "P", "2", "V"];

    loop c in cmds {
        if c == "1" || c == "2" || c == "3" || c == "4" {
            selected = true;
            paid = false;
        }
        if c == "P" {
            if selected {
                paid = true;
            } else {
                ignored = ignored + 1;
                selected = false;
                paid = false;
            }
        }
        if c == "V" {
            if selected && paid {
                dispenses = dispenses + 1;
                selected = false;
                paid = false;
            } else {
                ignored = ignored + 1;
                selected = false;
                paid = false;
            }
        }
    }

    fx {
        println("SuccessfulDispenses: ", dispenses);
        println("IgnoredCommands: ", ignored);
    }
    ret;
}

fn main() -> Void {
    let layout: Int[] = [0, 0, 0, 1, 1, 0, 0, 0, 0, 1, 0, 0, 1, 0];
    let n: Int = length(layout);
    let found: Bool = false;
    let start: Int = 0;
    let end: Int = 0;
    let i: Int = 0;
    loop i < n {
        if layout[i] == 0 {
            let runStart: Int = i;
            loop i < n && layout[i] == 0 {
                i = i + 1;
            }
            let runLen: Int = i - runStart;
            if runLen >= 3 && !found {
                found = true;
                start = runStart + 1;
                end = runStart + 3;
            }
        } else {
            i = i + 1;
        }
    }
