type Pallet {
    weight: Int = 0;
    number: Int = 0;
    rank: Int = 0;
}

fn main() -> Void {
    let weights: Int[] = [75, 82, 75, 91, 68, 82, 75, 91, 68, 82];
    let pallets: Pallet[] = [];
    loop i in 0..length(weights) {
        pallets = pallets + [new Pallet { weight: weights[i], number: i + 1 }];
    }

    // selection sort: descending by weight, ascending by pallet number
    let n: Int = length(pallets);
    loop i in 0..n {
        let bestIdx: Int = i;
        loop j in i + 1..n {
            if pallets[j].weight > pallets[bestIdx].weight {
                bestIdx = j;
            } else if pallets[j].weight == pallets[bestIdx].weight && pallets[j].number < pallets[bestIdx].number {
                bestIdx = j;
            }
        }
        if bestIdx != i {
            let tmp: Pallet = pallets[i];
            pallets[i] = pallets[bestIdx];
            pallets[bestIdx] = tmp;
        }
    }

    // assign ranks: competition ranking (1,2,2,4)
    pallets[0].rank = 1;
    loop i in 1..n {
        if pallets[i].weight == pallets[i - 1].weight {
            pallets[i].rank = pallets[i - 1].rank;
        } else {
            pallets[i].rank = pallets[i - 1].rank + 1;
        }
    }

    fx {
        loop i in 0..n {
            println("PALLET ", pallets[i].number, " WEIGHT ", pallets[i].weight, " RANK ", pallets[i].rank);
        }
    }
    ret;
}

